              steps: ['ip dhcp pool KAT1', 'network 10.64.10.0 255.255.255.0', 'default-router 10.64.10.1', 'dns-server 198.51.100.53', 'domain-name lab.example', 'exit'],
              check: s => { const p = s.model.dhcpPools.KAT1; return !!p && p.network === '10.64.10.0' && p.mask === '255.255.255.0' && p.gw[0] === '10.64.10.1' && p.dns.includes('198.51.100.53') && p.domain === 'lab.example'; },
